def smallestStackOutput(s):
    n = len(s)
    suf = ['{'] * (n + 1)
    for i in range(n - 1, -1, -1):
        suf[i] = min(s[i], suf[i + 1])
    stack, out = [], []
    for i, c in enumerate(s):
        stack.append(c)
        while stack and stack[-1] <= suf[i + 1]:
            out.append(stack.pop())
    while stack:
        out.append(stack.pop())
    return "".join(out)
